const Btn = ({
  children,
  onClick,
  variant = "primary",
  size = "md",
  style = {},
  disabled = false,
  icon,
}) => {
  const bg = {
    primary: COLORS.accent,
    danger: COLORS.redSoft,
    success: COLORS.greenSoft,
    ghost: "transparent",
    secondary: COLORS.surfaceAlt,
  };
  const cl = {
    primary: COLORS.accentText,
    danger: COLORS.red,
    success: COLORS.green,
    ghost: COLORS.textDim,
    secondary: COLORS.textPrimary,
  };
  const pd =
    size === "sm" ? "6px 14px" : size === "lg" ? "14px 32px" : "10px 20px";
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 7,
        padding: pd,
        background: bg[variant],
        border: `1px solid ${
          variant === "ghost"
            ? COLORS.border
            : variant === "danger"
            ? COLORS.red
            : variant === "success"
            ? COLORS.green
            : variant === "primary"
            ? COLORS.accent
            : COLORS.border
        }`,
        borderRadius: 9,
        color: cl[variant],
        fontSize: size === "sm" ? 12 : 14,
        fontWeight: 700,
        cursor: disabled ? "not-allowed" : "pointer",
        opacity: disabled ? 0.5 : 1,
        transition: "all 0.15s",
        ...style,
      }}
    >
      {icon && <IC n={icon} s={size === "sm" ? 13 : 16} />}
      {children}
    </button>
  );
};

